@page "/category/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="list-group mt-3">
            @foreach (var recipe in Recipes)
            {
                <a href="/recipe/@recipe.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5 class="mb-1">@recipe.Title</h5>
                        @if (recipe.RatingCount > 0)
                        {
                            <span class="badge bg-warning text-dark">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount)
                            </span>
                        }
                    </div>
                </a>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-danger">Recipe not found.</div>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="card mb-4">
            <div class="card-header"><strong>Ingredients</strong></div>
            <div class="card-body">
                <ul class="mb-0">
                    @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-header"><strong>Steps</strong></div>
            <div class="card-body">
                @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p class="mb-1">@step</p>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-header"><strong>Rate this Recipe</strong></div>
            <div class="card-body">
                <StarRating RecipeId="@Recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipe(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-3">
    <div>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="fs-3" style="cursor: pointer;" @onclick="() => Rate(star)">
                @(star <= SelectedRating ? "★" : "☆")
            </span>
        }
    </div>
    @if (SelectedRating > 0)
    {
        <span class="text-success">You rated this @SelectedRating/5!</span>
    }
    @if (AverageRating > 0)
    {
        <span class="text-muted">Average: @AverageRating.ToString("F1") (@RatingCount ratings)</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private double AverageRating { get; set; }
    private int RatingCount { get; set; }

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community.</p>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <strong>Thank you!</strong> Your recipe has been submitted successfully.
            <a href="/">Return to home</a>
        </div>
    }
    else
    {
        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Model.Title" />
                <ValidationMessage For="() => Model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
                <ValidationMessage For="() => Model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="4"
                    @bind-Value="Model.Ingredients"
                    placeholder="Separate ingredients with commas" />
                <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6"
                    @bind-Value="Model.Steps"
                    placeholder="Describe each step on a new line" />
                <ValidationMessage For="() => Model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(Model);
        Submitted = true;
    }
}

